-- Exact atomic name group, prepared for future tag commands. No RPC command
-- is enabled here. Proposed payloads must already contain the correct key.
create function sync_private.valid_tag_name_v1(value jsonb)
returns boolean language plpgsql immutable set search_path = '' as $$
declare name text; units integer;
begin
  if not sync_private.exact_keys(value,array['name','normalized_name'])
    or jsonb_typeof(value->'name') is distinct from 'string'
    or jsonb_typeof(value->'normalized_name') is distinct from 'string' then
    return false;
  end if;
  name := value->>'name';
  if name='' or name collate "C" is distinct from sync_private.clean_tag_name_v1(name) collate "C" then return false; end if;
  select sum(case when ascii(substr(name,n,1))>65535 then 2 else 1 end) into units
    from generate_series(1,length(name)) as n;
  return units <= 80 and (value->>'normalized_name') collate "C"
    = sync_private.normalized_tag_name_v1(name) collate "C";
end
$$;

revoke all on function sync_private.clean_tag_name_v1(text),
  sync_private.normalized_tag_name_v1(text), sync_private.valid_tag_name_v1(jsonb)
  from public, anon, authenticated, service_role;
grant execute on function sync_private.clean_tag_name_v1(text),
  sync_private.normalized_tag_name_v1(text), sync_private.valid_tag_name_v1(jsonb)
  to dourstuff_rpc;

